SET search_path TO lms, extensions;

CREATE TYPE whatsapp_status AS ENUM ('pending', 'sent', 'failed', 'delivered');

CREATE TABLE lms.whatsapp_logs (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  recipient_id  UUID NOT NULL REFERENCES lms.users(id),
  phone_number  TEXT NOT NULL,
  template_name TEXT NOT NULL,
